_GRAMS_RE = re.compile(r"(\d+(?:[.,]\d+)?)\s*(?:g|gr|gram)\b", re.IGNORECASE)


def _extract_grams(text):
    """Sorgudan gram miktarını yakala (ör. '300g tavuk' → 300.0). Yoksa None."""
    m = _GRAMS_RE.search(text or "")
    if m:
        try:
            val = float(m.group(1).replace(",", "."))
            if 0 < val <= 5000:
                return val
        except ValueError:
            pass
    return None


def _coach_search_food(query):
    """Birleşik besin araması — alaka-kapısı + TR→EN normalizasyonlu.

    1) Ham sorguyla FatSecret dene (İngilizce sorgular ve marka adları doğrudan
       eşleşir). Sonuçları ALAKA filtresinden geçir: FatSecret eşleyemediği
       Türkçe sorgulara ilgisiz jenerik besin döndürdüğü için ('patates
       kızartması' → 'Soy Nuts') ad-token örtüşmesi olmayanları ele.
    2) Alakalı sonuç yoksa sorguyu İngilizce'ye çevirip tekrar dene — FatSecret
       verisi ağırlıklı İngilizce, Türkçe serbest metin nadiren eşleşir.
    3) Son çare: statik Türkçe tablo, sonra LLM tahmini.
    Hepsi 100g bazlı 'per_100g' makroları içerir."""
    raw = (query or "").strip()

    relevant = [r for r in (_food_search_fatsecret(raw) or [])
                if _is_relevant_food(raw, r.get("name", ""))]
    if relevant:
        return relevant

    english = _normalize_food_query_en(raw)
    if english and english.lower() != raw.lower():
        relevant = [r for r in (_food_search_fatsecret(english) or [])
                    if _is_relevant_food(english, r.get("name", ""))]
        if relevant:
            return relevant

    return _food_search_static(raw) or _food_search_llm(english or raw) or []


def _today_nutrition_totals(user_id):
    """Bugünün beslenme toplamları (MealLog — tek kanonik beslenme defteri).
    menu.py'deki 'consumed' ile AYNI tarih anahtarını (utcnow %d.%m) kullanır ki
    koçun 'kalan bütçe'si ile menü analizinin 'kalanı' birebir tutarlı olsun.
    (Faz C tarih semantiğini tüm okuyucularda birlikte ISO/Istanbul'a taşıyacak.)"""
    today_key = day_key()
    row = db.session.query(
        db.func.coalesce(db.func.sum(MealLog.kalori), 0),
        db.func.coalesce(db.func.sum(MealLog.protein), 0),
        db.func.coalesce(db.func.sum(MealLog.karb), 0),
        db.func.coalesce(db.func.sum(MealLog.yag), 0),
        db.func.count(MealLog.id),
    ).filter(
        MealLog.user_id == user_id,
        MealLog.tarih == today_key,
    ).first()
    return {
        "calories": round(row[0]),
        "protein": round(row[1], 1),
        "carbs": round(row[2], 1),
        "fat": round(row[3], 1),
        "entry_count": row[4],
    }


def _remaining_macros_for_user(user_id):
    """Kullanicinin bugun KALAN gunluk makro butcesi.

    UserSession hedef kalorisinden hedef-makro dagilimi (analyze_menu ile ayni
    formul) cikarilir, bugun MealLog'a islenen tuketim dusulur.
    Deterministik; LLM yok. Profil/hedef yoksa None doner.
    """
    sess = (UserSession.query.filter_by(user_id=user_id)
            .order_by(UserSession.created_at.desc()).first())
    if not sess or not sess.target_calories:
        return None
    target_cal = sess.target_calories
    goal = sess.goal or ""
    protein_target = target_cal * (0.30 if goal == "kas kazanma" else 0.25) / 4
    fat_target = target_cal * 0.25 / 9
    carb_target = target_cal * (0.45 if goal == "kas kazanma" else 0.50) / 4
    consumed = _today_nutrition_totals(user_id)
    return {
        "calories": max(target_cal - consumed["calories"], 0),
        "protein": max(protein_target - consumed["protein"], 0),
        "carbs": max(carb_target - consumed["carbs"], 0),
        "fat": max(fat_target - consumed["fat"], 0),
    }


def _today_workout_totals(user_id):
    """Bugünün antrenman toplam volümü (Istanbul günü; created_at UTC olduğu için
    UTC sınırlarıyla karşılaştırılır)."""
    start, end = utc_day_bounds()
    row = db.session.query(
        db.func.coalesce(db.func.sum(WorkoutLog.volume), 0),
        db.func.count(WorkoutLog.id),
    ).filter(
        WorkoutLog.user_id == user_id,
        WorkoutLog.created_at >= start,
        WorkoutLog.created_at < end,
        # D4: UI tamamlama-işaretçisi (volume=0) gerçek egzersiz değil; koç
        # bağlamındaki "bugünkü hacim/egzersiz sayısı"nı şişirmesin (entry_count'ı
        # kabartıyordu). "Antrenman yapıldı mı" sinyali ayrı yollardan (nudge/
        # PumpCheck) hâlâ işaretçiyi görür.
        WorkoutLog.exercise_name != WORKOUT_COMPLETION_MARKER,
    ).first()
    return {"total_volume": round(row[0], 1), "entry_count": row[1]}


def _tool_fetch_nutrition_and_stage_log(user_id, food_query):
    """TOOL (staging): FatSecret'tan makro çek → PendingAction'a yaz → LLM'e döndür.
    KALICI KAYIT YAPMAZ. Durum geçişi: (yok) → staged."""
    food_query = (food_query or "").strip()
    if not food_query:
        return json.dumps({"status": "error", "message": "Yiyecek sorgusu boş."}, ensure_ascii=False)

    results = _coach_search_food(food_query)
    if not results:
        # FatSecret/fallback boş → LLM kullanıcıdan netleştirme istesin (hata yönetimi).
        return json.dumps({
            "status": "not_found",
            "message": f"'{food_query}' için besin verisi bulunamadı. Kullanıcıdan daha açık bir tanım iste (pişirme şekli, marka, miktar).",
        }, ensure_ascii=False)

    top = results[0]
    per_100g = top.get("per_100g") or top.get("macros") or {}
    grams = _extract_grams(food_query) or 100.0
    scale = grams / 100.0
    payload = {
        # B5: get(..., 0) açık None değerinde 0 vermez → float(None) TypeError.
        # `or 0` ile None/boş değerleri de 0'a indir.
        "food_name": (top.get("name") or food_query)[:200],
        "calories": round(float(per_100g.get("calories") or 0) * scale, 1),
        "protein": round(float(per_100g.get("protein") or 0) * scale, 1),
        "carbs": round(float(per_100g.get("carbs") or 0) * scale, 1),
        "fat": round(float(per_100g.get("fat") or 0) * scale, 1),
        "serving_size": f"{grams:g} g",
    }

    # Deterministik uyum degerlendirmesi (compatibility_score 0-100). Tum matematik
    # nutrition_pipeline'da yapilir; LLM yalnizca bu sabit sayilari sunar.
    remaining = _remaining_macros_for_user(user_id)
    evaluation = None
    if remaining is not None:
        evaluation = nutrition_pipeline.build_evaluation(
            food_id=top.get("food_id", ""),
            name=payload["food_name"],
            standardized_serving=payload["serving_size"],
            macros={
                "calories": payload["calories"],
                "protein": payload["protein"],
                "carbs": payload["carbs"],
                "fat": payload["fat"],
            },
            remaining=remaining,
        )

    # Tek aktif 'staged' meal: önceki bekleyenleri temizle, yenisini yaz, commit et.
    _cleanup_stale_pending(user_id)
    PendingAction.query.filter_by(user_id=user_id, action_type="log_meal").delete()
    db.session.add(PendingAction(user_id=user_id, action_type="log_meal", payload=payload))
    db.session.commit()

    return json.dumps({
        "status": "staged",
        "staged_food": payload,
        "evaluation": evaluation,
        "instruction": ("Makroları ve (varsa) compatibility_score'u kullanıcıya AYNEN, "
                        "değiştirmeden ve yeniden hesaplamadan sun — sayılar kesindir. "
                        "Sonra 'Günlüğüne kaydedeyim mi?' diye onay iste; onay gelmeden "
                        "confirm_and_commit_meal_log çağırma."),
    }, ensure_ascii=False)


def _tool_confirm_and_commit_meal_log(user_id):
    """TOOL (commit): En son staged meal'i kalıcı MealLog kaydına taşı (tek kanonik
    beslenme defteri — diyari/menü ile aynı tablo), PendingAction satırını sil.
    Durum geçişi: staged → committed."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id, action_type="log_meal")
               .order_by(PendingAction.created_at.desc())
               .first())
    if not pending:
        # 'evet' dendi ama ortada bekleyen yemek yok → güvenli hata yönetimi.
        return json.dumps({
            "status": "no_pending",
            "message": "Onaylanacak bekleyen bir yemek kaydı yok. Önce kullanıcının ne yediğini öğrenip fetch_nutrition_and_stage_log çağır.",
        }, ensure_ascii=False)

    data = pending.payload or {}
    cal = float(data.get("calories", 0) or 0)
    pro = float(data.get("protein", 0) or 0)
    carb = float(data.get("carbs", 0) or 0)
    fat = float(data.get("fat", 0) or 0)
    name = (data.get("food_name") or "Yemek")[:200]

    # Staged makrolar (FatSecret/LLM kaynaklı) porsiyon-sanity kapısından geçmeden
    # kanonik deftere yazılıyordu — diyari/menü/UI hepsi kısarken koç yolu atlıyordu.
    # Fiziksel olarak imkânsız bir porsiyonu (örn. 9999 kcal) makul tavanlara kıs.
    clamped = nutrition_pipeline.clamp_serving_macros(cal, pro, carb, fat)
    if clamped != (cal, pro, carb, fat):
        current_app.logger.warning(
            "[COACH] Staged makrolar makul değil (%s) — kısılıyor %s → %s",
            name, (cal, pro, carb, fat), clamped)
        cal, pro, carb, fat = clamped

    # Satırı önce atomik 'sahiplen': eşzamanlı çift-onayda (double-confirm) yalnızca
    # biri 1 satır siler; diğeri 0 alır ve çift loglamadan döner (3.10 idempotent).
    claimed = PendingAction.query.filter_by(id=pending.id).delete(synchronize_session=False)
    if not claimed:
        db.session.rollback()
        return json.dumps({
            "status": "no_pending",
            "message": "Bu kayıt zaten işlendi.",
        }, ensure_ascii=False)

    db.session.add(MealLog(
        user_id=user_id, ogun="AI Koç", yemekler=name,
        kalori=cal, protein=pro, karb=carb, yag=fat,
        tarih=day_key(), source="coach",
    ))
    award_xp(user_id, 10)
    log_activity(user_id, "nutrition_logged", f"{name} — {round(cal)} kcal")
    db.session.commit()

    return json.dumps({
        "status": "committed",
        "logged": {
            "food_name": name, "calories": cal, "protein": pro,
            "carbs": carb, "fat": fat, "serving_size": data.get("serving_size", ""),
        },
        "xp_awarded": 10,
        "today_totals": _today_nutrition_totals(user_id),
    }, ensure_ascii=False)


_PENDING_TTL = timedelta(hours=1)


def _cleanup_stale_pending(user_id, max_age=_PENDING_TTL):
    """Onaylanmadan bayatlamış (>1 saat) bekleyen aksiyonları toplu sil (3.10).

    Onay hiç gelmeyen 'staged' kayıtlar birikip sonraki bir 'evet'te yanlış/eski
    bir yemeği loglayabilir; periyodik toplu temizlik bu riski kapatır. Commit
    çağırana bırakılmaz — kendi içinde idempotenttir, hata boğulur."""
    try:
        cutoff = datetime.utcnow() - max_age
        deleted = (PendingAction.query
                   .filter(PendingAction.user_id == user_id,
                           PendingAction.created_at < cutoff)
                   .delete(synchronize_session=False))
        if deleted:
            current_app.logger.info(
                "[PENDING] %d bayat bekleyen aksiyon temizlendi (user=%s)", deleted, user_id)
    except Exception:
        db.session.rollback()


def _tool_stage_workout_log(user_id, exercise_name, sets, reps, weight_kg):
    """TOOL (staging): Antrenmanı onaya hazırla. Kalıcı kayıt yapmaz."""
    exercise_name = (exercise_name or "").strip()
    if not exercise_name:
        return json.dumps({"status": "error", "message": "Egzersiz adı boş."}, ensure_ascii=False)
    try:
        sets = int(sets or 0)
        reps = int(reps or 0)
        weight = float(weight_kg or 0)
    except (TypeError, ValueError):
        sets, reps, weight = 3, 10, 0.0
    if sets <= 0:
        sets = 3
    if reps <= 0:
        reps = 10
    if weight < 0:
        weight = 0.0

    payload = {
        "exercise_name": exercise_name[:120],
        "sets": sets, "reps": reps, "weight_kg": weight,
        "volume": round(sets * reps * weight, 1),
    }
    _cleanup_stale_pending(user_id)
    PendingAction.query.filter_by(user_id=user_id, action_type="log_workout").delete()
    db.session.add(PendingAction(user_id=user_id, action_type="log_workout", payload=payload))
    db.session.commit()

    return json.dumps({
        "status": "staged",
        "staged_workout": payload,
        "instruction": "Antrenmanı özetle ve onay iste; onay gelince confirm_and_commit_workout_log çağır.",
    }, ensure_ascii=False)


def _tool_confirm_and_commit_workout_log(user_id):
    """TOOL (commit): En son staged antrenmanı kalıcı WorkoutLog'a taşı."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id, action_type="log_workout")
               .order_by(PendingAction.created_at.desc())
               .first())
    if not pending:
        return json.dumps({
            "status": "no_pending",
            "message": "Onaylanacak bekleyen bir antrenman kaydı yok.",
        }, ensure_ascii=False)

    d = pending.payload or {}
    # Satırı önce atomik 'sahiplen' (double-confirm idempotency — 3.10).
    claimed = PendingAction.query.filter_by(id=pending.id).delete(synchronize_session=False)
    if not claimed:
        db.session.rollback()
        return json.dumps({
            "status": "no_pending",
            "message": "Bu kayıt zaten işlendi.",
        }, ensure_ascii=False)

    db.session.add(WorkoutLog(
        user_id=user_id,
        exercise_name=(d.get("exercise_name") or "Egzersiz")[:120],
        sets=int(d.get("sets", 3)), reps=int(d.get("reps", 10)),
        weight_kg=float(d.get("weight_kg", 0)), volume=float(d.get("volume", 0)),
    ))
    award_xp(user_id, 15)
    log_activity(user_id, "workout_completed",
                 f"{d.get('exercise_name')} — {d.get('sets')}x{d.get('reps')} @ {d.get('weight_kg')}kg")
    db.session.commit()

    return json.dumps({
        "status": "committed",
        "logged": d,
        "xp_awarded": 15,
        "today_totals": _today_workout_totals(user_id),
    }, ensure_ascii=False)


def _tool_cancel_pending_log(user_id):
    """TOOL: Kullanıcı reddederse SON stage edilen kaydı sil (meal VEYA workout).

    Tüm bekleyenleri silmek yerine en yenisini hedefler — tek bir 'iptal' hem
    staged meal'i hem staged workout'u birden silmesin (#11). Kullanıcı genelde
    en son sunulan kaydı reddeder; o da en yeni olandır."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id)
               .order_by(PendingAction.created_at.desc(), PendingAction.id.desc())
               .first())
    if not pending:
        return json.dumps({"status": "cancelled", "removed": 0}, ensure_ascii=False)
    cancelled_type = pending.action_type
    removed = PendingAction.query.filter_by(id=pending.id).delete()
    db.session.commit()
    return json.dumps({"status": "cancelled", "removed": removed,
                       "cancelled_type": cancelled_type}, ensure_ascii=False)


# ── manage_user_memory ───────────────────────────────────────────────────────
# LLM'in yazabileceği anahtarlar beyaz-listede (rastgele anahtar şişmesini önle).
_MEMORY_KEYS = ("injuries", "fitness_goals", "equipment_available",
                "dietary_restrictions", "preferences")
_MEMORY_VALUE_MAXLEN = 2000  # serileştirilmiş değer üst sınırı (LLM girdisi)


def _tool_manage_user_memory(user_id, action, key=None, value=None):
    """TOOL: Kullanıcının uzun süreli metadata'sını (sakatlıklar, tercihler) oku/yaz.
    User.user_metadata (JSON) ile eşlenir. user_id ASLA LLM'den gelmez."""
    action = (action or "").strip().lower()
    key = (key or "").strip()
    user = db.session.get(User, user_id)
    if not user:
        return json.dumps({"status": "error", "message": "Kullanıcı bulunamadı."}, ensure_ascii=False)
    meta = dict(user.user_metadata or {})

    if action == "get":
        if key:
            return json.dumps({"status": "ok", "action": "get", "key": key,
                               "value": meta.get(key)}, ensure_ascii=False)
        return json.dumps({"status": "ok", "action": "get", "memory": meta}, ensure_ascii=False)

    if action == "update":
        if key not in _MEMORY_KEYS:
            return json.dumps({"status": "error",
                               "message": f"Geçersiz anahtar: '{key}'. Geçerli anahtarlar: {', '.join(_MEMORY_KEYS)}"},
                              ensure_ascii=False)
        # 'update' DAİMA bir değer ister. None/boş ile çağrı kayıtlı veriyi (ör.
        # sakatlık) sessizce silmesin — sakatlık akışında "yok" için 'Hiçbiri' yazılır.
        if value is None or (isinstance(value, str) and not value.strip()):
            return json.dumps({"status": "error",
                               "message": "'update' için boş olmayan bir value gerekli (silmek için açık bir değer gönder, ör. 'Hiçbiri')."},
                              ensure_ascii=False)
        try:
            if len(json.dumps(value, ensure_ascii=False)) > _MEMORY_VALUE_MAXLEN:
                return json.dumps({"status": "error", "message": "Değer çok uzun."}, ensure_ascii=False)
        except (TypeError, ValueError):
            return json.dumps({"status": "error", "message": "Değer JSON'a çevrilemedi."}, ensure_ascii=False)
        # JSON kolon: yerinde mutasyon SQLAlchemy tarafından izlenmez — yeni dict ata
        # + flag_modified ile değişikliği garanti et (aksi halde commit kalıcı olmaz).
        meta[key] = value
        user.user_metadata = meta
        flag_modified(user, "user_metadata")
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            current_app.logger.warning("[MEMORY] commit başarısız: %s: %s", type(e).__name__, e)
            return json.dumps({"status": "error", "message": "Kaydedilemedi, tekrar dene."}, ensure_ascii=False)
        return json.dumps({"status": "ok", "action": "update", "key": key,
                           "value": value}, ensure_ascii=False)

    return json.dumps({"status": "error",
                       "message": f"Geçersiz action: '{action}'. 'get' veya 'update' olmalı."},
                      ensure_ascii=False)


# ── query_fitx_metrics ────────────────────────────────────────────────────────
_VALID_DATE_RANGES = ("today", "last_7_days", "current_month")
_VALID_METRICS = ("calories", "water_ml", "sleep_hours", "weight_kg", "volume_lifted")


def _range_start_day(date_range):
    """date_range → aralığın BAŞLANGIÇ Istanbul günü (date). Bitiş daima bugün."""
    today = app_today()
    return {
        "today": today,
        "last_7_days": today - timedelta(days=6),
        "current_month": today.replace(day=1),
    }.get(date_range)


def _range_keys(date_range):
    """ISO-string tarih kolonları (MealLog.tarih, WaterLog.date_key) için (lo, hi)
    ISO anahtar çifti. 'YYYY-MM-DD' sözlüksel olarak sıralandığı için string
    karşılaştırması doğru aralığı verir: col >= lo AND col <= hi."""
    start = _range_start_day(date_range)
    return (start.isoformat(), app_today().isoformat()) if start else None


def _range_bounds(date_range):
    """datetime kolonları (created_at, naive UTC) için yarı-açık [start, end) UTC
    sınırları: col >= start AND col < end. utc_day_bounds Istanbul gününü baz alır."""
    start_day = _range_start_day(date_range)
    if not start_day:
        return None
    start, _ = utc_day_bounds(start_day)
    _, end = utc_day_bounds(app_today())
    return start, end


def _tool_query_fitx_metrics(user_id, metric_type, date_range):
    """TOOL: Kullanıcının geçmiş metriklerini parametrik (HAM SQL YOK) sorgula.
    Enum'lar beyaz-listede; her metrik sabit, güvenli bir sorguya eşlenir."""
    metric_type = (metric_type or "").strip()
    date_range = (date_range or "").strip()
    if metric_type not in _VALID_METRICS:
        return json.dumps({"status": "error",
                           "message": f"Geçersiz metric_type: '{metric_type}'. Geçerli: {', '.join(_VALID_METRICS)}"},
                          ensure_ascii=False)
    if date_range not in _VALID_DATE_RANGES:
        return json.dumps({"status": "error",
                           "message": f"Geçersiz date_range: '{date_range}'. Geçerli: {', '.join(_VALID_DATE_RANGES)}"},
                          ensure_ascii=False)

    if metric_type == "sleep_hours":
        # Uyku SÜRESİ (saat) verisi YOK; yalnızca subjektif kalite (1-5) var ve o da
        # [HAFTALIK CHECK-IN TRENDİ] bağlam bloğunda zaten sağlanıyor. Veri uydurma.
        return json.dumps({"status": "unsupported", "metric_type": "sleep_hours",
                           "message": "Uyku süresi (saat) takibi yok. Subjektif uyku "
                                      "kalitesi (1-5) için [HAFTALIK CHECK-IN TRENDİ] "
                                      "bağlam bloğuna bak."}, ensure_ascii=False)

    base = {"status": "ok", "metric_type": metric_type, "date_range": date_range}

    if metric_type == "calories":
        lo, hi = _range_keys(date_range)
        total = db.session.query(db.func.coalesce(db.func.sum(MealLog.kalori), 0)).filter(
            MealLog.user_id == user_id, MealLog.tarih >= lo, MealLog.tarih <= hi).scalar()
        return json.dumps({**base, "value": round(total or 0), "unit": "kcal"}, ensure_ascii=False)

    if metric_type == "water_ml":
        lo, hi = _range_keys(date_range)
        cups = db.session.query(db.func.coalesce(db.func.sum(WaterLog.count), 0)).filter(
            WaterLog.user_id == user_id, WaterLog.date_key >= lo, WaterLog.date_key <= hi).scalar()
        return json.dumps({**base, "value": round((cups or 0) * 240), "unit": "ml",
                           "detail": f"{cups or 0} bardak × 240 ml"}, ensure_ascii=False)

    if metric_type == "volume_lifted":
        start, end = _range_bounds(date_range)
        total = db.session.query(db.func.coalesce(db.func.sum(WorkoutLog.volume), 0)).filter(
            WorkoutLog.user_id == user_id,
            WorkoutLog.created_at >= start, WorkoutLog.created_at < end).scalar()
        return json.dumps({**base, "value": round(total or 0, 1), "unit": "kg"}, ensure_ascii=False)

    if metric_type == "weight_kg":
        start, end = _range_bounds(date_range)
        rows = (WeeklyLog.query.filter(
            WeeklyLog.user_id == user_id,
            WeeklyLog.created_at >= start, WeeklyLog.created_at < end)
            .order_by(WeeklyLog.created_at.asc()).all())
        if not rows:
            return json.dumps({**base, "value": None, "unit": "kg",
                               "message": "Bu aralıkta kilo kaydı yok."}, ensure_ascii=False)
        first, last = rows[0].weight, rows[-1].weight
        # L1: WeeklyLog.weight NULL olabilir; round(None, 1) TypeError atardı
        # (blanket except'e düşüp generic hataya dönerdi). None'ı açıkça karşıla.
        if last is None:
            return json.dumps({**base, "value": None, "unit": "kg",
                               "message": "Bu aralıkta geçerli kilo kaydı yok."}, ensure_ascii=False)
        change = round(last - first, 1) if first is not None else None
        return json.dumps({**base, "value": round(last, 1), "unit": "kg",
                           "change": change, "entries": len(rows)}, ensure_ascii=False)

    return json.dumps({"status": "error", "message": f"Bilinmeyen metric_type: {metric_type}"},
                      ensure_ascii=False)


# ── analyze_gym_photo (multimodal Pump Check) ─────────────────────────────────
def _parse_photo_validation(raw):
    """Modelin ham yanıtından {"is_gym":bool,"form_rating":1-10,"reason":str} ayıkla."""
    s = (raw or "").strip().replace("```json", "").replace("```", "")
    start = s.find("{")
    end = s.rfind("}") + 1
    if start != -1 and end > start:
        s = s[start:end]
    try:
        data = json.loads(s)
    except (json.JSONDecodeError, TypeError, ValueError):
        data = {}
    try:
        rating = int(data.get("form_rating") or 0)
    except (TypeError, ValueError):
        rating = 0
    rating = max(1, min(rating, 10)) if rating else 0  # 1..10'a kıs (0 = bilinmiyor)
    return {"is_gym": bool(data.get("is_gym", False)), "form_rating": rating,
            "reason": str(data.get("reason", ""))[:300]}


def _tool_analyze_gym_photo(user_id, s3_key):
    """TOOL: S3'teki bir antrenman fotoğrafını Bedrock (Sonnet) ile doğrula; geçerliyse
    günlük (idempotent) Pump Check ödülünü ver. user_id ASLA LLM'den gelmez; s3_key
    LLM'den gelir → sahiplik (IDOR) sınırı zorunlu."""
    s3_key = (s3_key or "").strip()
    if not s3_key:
        return json.dumps({"status": "error", "message": "s3_key boş."}, ensure_ascii=False)
    if not (BEDROCK_ENABLED and _anthropic is not None):
        return json.dumps({"status": "error", "message": "Görsel doğrulama (Bedrock) şu an etkin değil."},
                          ensure_ascii=False)
    if not s3_helper.is_enabled():
        return json.dumps({"status": "error", "message": "Görsel deposu (S3) yapılandırılmamış."},
                          ensure_ascii=False)

    # IDOR sınırı: anahtar bu kullanıcıya ait olmalı (yol içinde '/<user_id>/').
    try:
        image_bytes = s3_helper.get_object_bytes(s3_key, expected_user_id=user_id)
    except Exception as e:
        current_app.logger.info("[ANALYZE PHOTO] görsel alınamadı: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Görsel alınamadı veya sana ait değil."},
                          ensure_ascii=False)

    media_type = s3_helper.media_type_for_key(s3_key)
    try:
        if image_bytes and len(image_bytes) > 1_500_000:
            from app.services.menu_ocr import _compress_image_for_vision
            image_bytes, media_type = _compress_image_for_vision(image_bytes)
    except Exception:
        pass  # sıkıştırma başarısızsa ham baytlarla devam

    prompt = (
        "Sen bir fitness uygulamasının 'Pump Check' görsel doğrulayıcısısın. Görseli "
        "incele: bir spor salonu/antrenman ortamı mı? Kişinin fiziksel formunu/çabasını "
        "1-10 arası puanla. SADECE şu katı JSON'u döndür, başka hiçbir şey yazma: "
        '{"is_gym": true|false, "form_rating": 1-10, "reason": "kısa Türkçe gerekçe"}'
    )
    try:
        raw = _bedrock_validate_image(image_bytes, media_type, prompt, max_tokens=200)
    except Exception as e:
        current_app.logger.warning("[ANALYZE PHOTO] Bedrock başarısız: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Görsel analizi şu an yapılamadı."},
                          ensure_ascii=False)
    if not (raw or "").strip():
        # Boş model yanıtı (transport/model aksaklığı): _parse_photo_validation bunu
        # is_gym:false'a çevirip "burası spor salonu değil" gibi YANLIŞ bir cevaba
        # dönüştürürdü. Gerçek "değil" kararından ayır, hata olarak dön.
        current_app.logger.warning("[ANALYZE PHOTO] Bedrock boş yanıt döndürdü")
        return json.dumps({"status": "error", "message": "Görsel analizi şu an yapılamadı."},
                          ensure_ascii=False)
    result = _parse_photo_validation(raw)

    if not result["is_gym"]:
        return json.dumps({"status": "ok", "is_gym": False, "form_rating": result["form_rating"],
                           "reason": result["reason"], "awarded": False}, ensure_ascii=False)

    # İdempotent ödül: bugün zaten bir Pump Check varsa tekrar ödül YOK (XP farming'i önle).
    # /workout/complete ile aynı günlük-tamamlama defterini paylaşır.
    start_utc, end_utc = utc_day_bounds()
    if PumpCheck.query.filter(
        PumpCheck.user_id == user_id,
        PumpCheck.created_at >= start_utc,
        PumpCheck.created_at < end_utc,
    ).first():
        return json.dumps({"status": "already_done", "is_gym": True,
                           "form_rating": result["form_rating"], "reason": result["reason"],
                           "awarded": False, "message": "Bugünkü antrenmanını zaten tamamladın."},
                          ensure_ascii=False)

    db.session.add(PumpCheck(
        user_id=user_id, image_key=s3_key, location_type="ai_tool",
        description=result["reason"][:200], valid=True, fallback=False,
        date_key=app_today().isoformat()))
    db.session.add(WorkoutLog(
        user_id=user_id, exercise_name=WORKOUT_COMPLETION_MARKER,
        sets=1, reps=1, weight_kg=0, volume=0))
    xp = 35  # /workout/complete ile aynı: 10 base + 25 foto bonusu
    quest = _claim_quest(user_id, "workout_logged")
    award_xp(user_id, xp)
    log_activity(user_id, "workout_completed", "Pump Check doğrulandı (AI koç)")
    try:
        db.session.commit()
    except IntegrityError:
        # TOCTOU yarışı: başka bir istek (UI veya AI tool) bugünün PumpCheck'ini
        # araya yazdı; uq_pump_check_day ikinciyi reddetti → çift XP yok.
        db.session.rollback()
        return json.dumps({"status": "already_done", "is_gym": True,
                           "form_rating": result["form_rating"], "reason": result["reason"],
                           "awarded": False, "message": "Bugünkü antrenmanını zaten tamamladın."},
                          ensure_ascii=False)
    except Exception as e:
        db.session.rollback()
        current_app.logger.warning("[ANALYZE PHOTO] commit başarısız: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Ödül kaydedilemedi, tekrar dene."},
                          ensure_ascii=False)

    return json.dumps({"status": "committed", "is_gym": True,
                       "form_rating": result["form_rating"], "reason": result["reason"],
                       "awarded": True, "xp_awarded": xp + (quest["xp"] if quest else 0)},
                      ensure_ascii=False)


