def _to_openai_tool(t):
    """Kanonik tanım → OpenAI function-calling biçimi."""
    return {"type": "function", "function": {
        "name": t["name"], "description": t["description"], "parameters": t["parameters"]}}


def _to_anthropic_tool(t):
    """Kanonik tanım → Anthropic Messages API biçimi (input_schema = parameters)."""
    return {"name": t["name"], "description": t["description"], "input_schema": t["parameters"]}


# OpenAI döngüsü bu listeyi olduğu gibi kullanır (davranış değişmez).
COACH_TOOLS = [_to_openai_tool(t) for t in _COACH_TOOL_DEFS]
# Bedrock/Anthropic döngüsü için aynı kaynaktan türetilen biçim.
COACH_TOOLS_ANTHROPIC = [_to_anthropic_tool(t) for t in _COACH_TOOL_DEFS]


def _dispatch_coach_tool(user_id, name, arguments_json):
    """LLM'in istediği aracı sunucu tarafında çalıştır. user_id ASLA LLM'den
    gelmez — güvenlik için current_user'dan enjekte edilir. JSON string döndürür."""
    _assert_principal(user_id)
    try:
        args = json.loads(arguments_json) if arguments_json else {}
    except (json.JSONDecodeError, TypeError):
        args = {}

    # Araç gövdesindeki beklenmeyen hatayı (özellikle DB commit/delete) merkezi
    # olarak yakala: oturumu rollback ile temizle (kirli transaction sonraki
    # commit'i de patlatmasın) ve koç turunu çökertmek yerine modele hata durumu
    # döndür. _assert_principal KASTEN bunun DIŞINDA — güvenlik ihlali dostça bir
    # mesaja dönüşmemeli, propagate etmeli.
    try:
        if name == "fetch_nutrition_and_stage_log":
            return _tool_fetch_nutrition_and_stage_log(user_id, args.get("food_query", ""))
        if name == "confirm_and_commit_meal_log":
            return _tool_confirm_and_commit_meal_log(user_id)
        if name == "stage_workout_log":
            return _tool_stage_workout_log(
                user_id, args.get("exercise_name", ""),
                args.get("sets"), args.get("reps"), args.get("weight_kg"),
            )
        if name == "confirm_and_commit_workout_log":
            return _tool_confirm_and_commit_workout_log(user_id)
        if name == "cancel_pending_log":
            return _tool_cancel_pending_log(user_id)
        if name == "manage_user_memory":
            return _tool_manage_user_memory(
                user_id, args.get("action", ""), args.get("key"), args.get("value"))
        if name == "query_fitx_metrics":
            return _tool_query_fitx_metrics(
                user_id, args.get("metric_type", ""), args.get("date_range", ""))
        if name == "analyze_gym_photo":
            return _tool_analyze_gym_photo(user_id, args.get("s3_key", ""))
        return json.dumps({"status": "error", "message": f"Bilinmeyen araç: {name}"}, ensure_ascii=False)
    except Exception:
        db.session.rollback()
        current_app.logger.warning("[COACH] araç '%s' çalışırken hata", name, exc_info=True)
        return json.dumps({"status": "error",
                           "message": "Araç çalışırken bir hata oluştu, tekrar dener misin?"},
                          ensure_ascii=False)


COACH_HISTORY_LIMIT = 6          # son 3 alışveriş (user+assistant) yeterli bağlam


COACH_HISTORY_CHAR_CAP = 400     # her turu kırp ki istem şişmesin


def _sanitize_client_history(raw):
    """Widget'ın gönderdiği konuşma geçmişini güvenli OpenAI mesajlarına çevir.

    Widget formatı: [{"role": "user"|"bot", "text": "..."}]. 'bot' → 'assistant'
    eşlenir, metin kırpılır, yalnızca düz-metin user/assistant turları geçer
    (tool/sistem rolleri client'tan KABUL EDİLMEZ). Bozuk girdi sessizce atlanır."""
    if not isinstance(raw, list):
        return []
    out = []
    for item in raw[-COACH_HISTORY_LIMIT:]:
        if not isinstance(item, dict):
            continue
        role = item.get("role")
        role = "assistant" if role in ("bot", "assistant") else "user" if role == "user" else None
        if role is None:
            continue
        text = item.get("text") or item.get("content") or ""
        if not isinstance(text, str):
            continue
        text = text.strip()
        if text:
            content = text[:COACH_HISTORY_CHAR_CAP]
            # B15: Anthropic ardışık aynı-rol turlarında 400 verir; iki user (veya
            # iki assistant) turu arka arkaya gelirse birleştir ki Bedrock çağrısı
            # 400'lenip sessizce gpt-4o-mini yedeğine düşmesin.
            if out and out[-1]["role"] == role:
                merged = f"{out[-1]['content']}\n{content}"[:COACH_HISTORY_CHAR_CAP]
                out[-1]["content"] = merged
            else:
                out.append({"role": role, "content": content})
    return out


_COACH_TOOL_LOOP_CAP = 5  # araç çağrısı zincirine güvenli üst sınır (iki sağlayıcı)


class _BedrockFallback(Exception):
    """Bedrock döngüsü İLK çağrıda (henüz hiçbir araç çalışmadan) hata verdiğinde
    fırlatılır → OpenAI'ya güvenle düşülebilir. Bir araç YAN ETKİ ürettikten sonra
    oluşan hatalar bunu fırlatmaz (yarıda sağlayıcı değiştirip aracı tekrar
    çalıştırmaktan kaçınmak için)."""


def _run_coach_conversation(user_id, question, context, client_history=None, language="tr"):
    """Koç sohbeti yönlendiricisi: ortak mesajları kurar, Bedrock açıksa Bedrock
    araç-kullanım döngüsünü dener (ilk çağrı hatasında OpenAI'ya şeffafça düşer),
    aksi halde mevcut OpenAI döngüsünü çalıştırır; sonra geçmişi kalıcılaştırır.

    Konuşma geçmişi kullanıcının GÖRDÜĞÜ sohbettir: widget her istekte `history`
    gönderir, biz onu kaynak-doğru kabul ederiz. Asıl 'staged' veri DB'deki
    PendingAction'da yaşar. Client geçmiş göndermezse eski session-cookie'sine düşülür.
    """
    use_client = client_history is not None
    if use_client:
        history = _sanitize_client_history(client_history)
        # Widget mevcut soruyu da history'nin sonuna iter; soruyu aşağıda biz
        # ayrıca eklediğimiz için sondaki user turlarını atıp çift eklemeyi önle.
        while history and history[-1]["role"] == "user":
            history.pop()
    else:
        history = list(session.get("coach_history", []))
    history = history[-COACH_HISTORY_LIMIT:]

    final_text = None
    if BEDROCK_ENABLED and _anthropic is not None:
        try:
            final_text = _run_coach_conversation_bedrock(user_id, question, context, history, language)
        except _BedrockFallback as e:
            current_app.logger.warning(
                "[COACH] Bedrock ilk çağrı başarısız, OpenAI'ya düşülüyor: %s", e)
            final_text = None
    if final_text is None:
        final_text = _run_coach_conversation_openai(user_id, question, context, history, language)

    is_error_fallback = not final_text
    if not final_text:
        final_text = _COACH_FALLBACKS[_coach_lang(language)]["error"]

    # Geçmiş client'ta (widget sessionStorage) tutuluyor; client modunda session'a
    # YAZMA. Yalnızca client history göndermezse eski cookie geçmişini güncelle.
    # B16: sağlayıcı hata-yedeği metnini geçmişe YAZMA — aksi halde bir sonraki
    # turda bağlam olarak geri beslenip modeli kirletiyordu.
    if not use_client and not is_error_fallback:
        new_history = history + [
            {"role": "user", "content": question[:COACH_HISTORY_CHAR_CAP]},
            {"role": "assistant", "content": final_text[:COACH_HISTORY_CHAR_CAP]},
        ]
        session["coach_history"] = new_history[-COACH_HISTORY_LIMIT:]
    return final_text


def _run_coach_conversation_openai(user_id, question, context, history, language="tr"):
    """OpenAI function-calling döngüsü: system → (gerekirse araç çağrıları) → final metin.
    Geçmişi session'a YAZMAZ (çağıran yönlendirici halleder)."""
    messages = [{"role": "system", "content": build_coach_system(language)}]
    if context:
        messages.append({"role": "system", "content": f"[KULLANICI VERİSİ]\n{context}"})
    messages.extend(history)
    messages.append({"role": "user", "content": question})

    final_text = ""
    for _ in range(_COACH_TOOL_LOOP_CAP):
        try:
            resp = openai_client.chat.completions.create(
                model=OPENAI_MODEL,
                messages=messages,
                tools=COACH_TOOLS,
                tool_choice="auto",
                max_tokens=700,
                temperature=0.6,
            )
        except Exception as e:
            current_app.logger.warning("[COACH] OpenAI çağrısı başarısız: %s", type(e).__name__)
            return _COACH_FALLBACKS[_coach_lang(language)]["error"]
        if not resp.choices:
            # İçerik filtresi boş choices döndürebilir; ham IndexError yerine
            # boş final_text ile çık (çağıran yönlendirici dostça mesaja düşer).
            current_app.logger.warning("[COACH] OpenAI boş choices döndürdü")
            break
        msg = resp.choices[0].message
        tool_calls = msg.tool_calls or []

        if not tool_calls:
            final_text = msg.content or ""
            break

        # Araç isteyen assistant mesajını (tool_calls ile) sıraya ekle.
        messages.append({
            "role": "assistant",
            "content": msg.content or "",
            "tool_calls": [
                {"id": tc.id, "type": "function",
                 "function": {"name": tc.function.name, "arguments": tc.function.arguments}}
                for tc in tool_calls
            ],
        })
        # Her tool_call_id için tam olarak bir 'tool' yanıtı ekle (API zorunluluğu).
        for tc in tool_calls:
            result = _dispatch_coach_tool(user_id, tc.function.name, tc.function.arguments)
            messages.append({"role": "tool", "tool_call_id": tc.id, "content": result})
        # Döngü başa döner: model araç sonuçlarıyla final metni üretir ya da zincirler.
    else:
        final_text = _COACH_FALLBACKS[_coach_lang(language)]["tool"]
    return final_text


def _build_bedrock_system(context, language="tr"):
    """Bedrock `system` parametresini kur. Caching açıkken dile özgü sistem
    promptunu ephemeral cache breakpoint ile işaretle; DEĞİŞKEN [KULLANICI VERİSİ]
    daima önbelleğe-alınan bloğun SONRASINA gelir (asla içine gömülmez — sessiz
    invalidasyon). Caching kapalıyken düz string yeterli."""
    system_prompt = build_coach_system(language)
    if BEDROCK_PROMPT_CACHE:
        blocks = [{"type": "text", "text": system_prompt,
                   "cache_control": {"type": "ephemeral"}}]
        if context:
            blocks.append({"type": "text", "text": f"[KULLANICI VERİSİ]\n{context}"})
        return blocks
    sys = system_prompt
    if context:
        sys += f"\n\n[KULLANICI VERİSİ]\n{context}"
    return sys


def _anthropic_tools_for_call():
    """COACH_TOOLS_ANTHROPIC'in çağrı-zamanı kopyası. Caching açıkken SON araca bir
    cache breakpoint ekler (sıra sabit → stabil önbellek). Temel liste kirletilmez."""
    if not (BEDROCK_PROMPT_CACHE and COACH_TOOLS_ANTHROPIC):
        return COACH_TOOLS_ANTHROPIC
    tools = [dict(t) for t in COACH_TOOLS_ANTHROPIC]
    tools[-1] = {**tools[-1], "cache_control": {"type": "ephemeral"}}
    return tools


def _first_text_block(resp):
    for block in getattr(resp, "content", None) or []:
        if getattr(block, "type", None) == "text":
            return block.text or ""
    return ""


def _run_coach_conversation_bedrock(user_id, question, context, history, language="tr"):
    """Bedrock (Anthropic Messages API) araç-kullanım döngüsü. stop_reason=='tool_use'
    olduğu sürece araçları çalıştırır, tool_result'ları geri besler ve modelin final
    metnine (stop_reason=='end_turn') ulaşana dek zincirler (güvenli üst sınır).

    İlk create() çağrısı hiçbir araç çalışmadan hata verirse _BedrockFallback fırlatır
    (yönlendirici OpenAI'ya düşer). Bir araç YAN ETKİ ürettikten sonraki hatada
    sağlayıcı DEĞİŞTİRİLMEZ — yumuşak hata metni döner."""
    system = _build_bedrock_system(context, language)
    tools = _anthropic_tools_for_call()
    convo = [dict(m) for m in history] + [{"role": "user", "content": question}]
    # Anthropic ilk mesajın 'user' rolünde olmasını şart koşar; baştaki assistant
    # turlarını (ör. widget'ın açılış bot mesajı) at — aksi halde ilk çağrı 400 verir.
    while convo and convo[0].get("role") != "user":
        convo.pop(0)
    max_tokens = min(700, BEDROCK_MAX_TOKENS)

    tools_ran = 0
    for _ in range(_COACH_TOOL_LOOP_CAP):
        # B4: create() YANINDA yanıt ayrıştırma da korunmalı — `resp.content` None
        # (→ TypeError) gibi create sonrası hatalar önceden _BedrockFallback DIŞINDA
        # kaçıp yönlendiricinin OpenAI yedeğini atlayarak koçu 500'lüyordu. Aynı
        # tools_ran mantığını uygula: hiç araç çalışmadıysa OpenAI'ya düş, çalıştıysa
        # sağlayıcı değiştirme (yan etkiyi tekrarlama) → yumuşak hata.
        try:
            resp = bedrock_client.messages.create(
                model=BEDROCK_MODEL,
                max_tokens=max_tokens,
                system=system,
                messages=convo,
                tools=tools,
            )

            if getattr(resp, "stop_reason", None) != "tool_use":
                text = _first_text_block(resp)
                if text:
                    return text
                # Metin bloğu yok: hiç araç çalışmadıysa OpenAI'ya düş (soru
                # cevaplanabilirdi); araç çalıştıysa sağlayıcı değiştirme.
                if tools_ran == 0:
                    raise _BedrockFallback("boş Bedrock yanıtı (metin bloğu yok)")
                return "İşlemi tamamlayamadım, tekrar dener misin?"

            # Araç isteyen assistant turunu (tool_use bloklarıyla) olduğu gibi ekle.
            convo.append({"role": "assistant", "content": resp.content})
            tool_results = []
            for block in resp.content:
                if getattr(block, "type", None) == "tool_use":
                    out = _dispatch_coach_tool(user_id, block.name, json.dumps(block.input or {}))
                    tool_results.append({"type": "tool_result", "tool_use_id": block.id, "content": out})
                    tools_ran += 1
            convo.append({"role": "user", "content": tool_results})
        except _BedrockFallback:
            raise
        except Exception as e:
            if tools_ran == 0:
                raise _BedrockFallback(f"{type(e).__name__}: {e}")
            current_app.logger.warning("[COACH][Bedrock] araç sonrası çağrı/ayrıştırma hatası: %s", e)
            return "İşlemi tamamlayamadım, tekrar dener misin?"
        # Döngü başa döner: model araç sonuçlarıyla final metni üretir ya da zincirler.

    return "İşlemi tamamlayamadım, tekrar dener misin?"


def generate_coach_reply(name, age, gender, weight, height,
                         goal, level, current_activity,
                         bmr, tdee, target_calories,
                         training_plan, nutrition_plan,
                         user_message,
                         previous_weight=None, days_passed=None, language="tr"):

    activity_labels = {
        "sedentary"  : "hareketsiz (masa başı iş)",
        "active"     : "aktif (haftada 3-5 gün)",
        "very_active": "çok aktif (haftada 5-6 gün)"
    }
    activity_text = activity_labels.get(current_activity, current_activity)

    # Önceki ilerleme metni
    diff = 0
    sure = "0 gün"
    progress_text = "İlk kayıt — geçmiş veri yok."
    if previous_weight and days_passed is not None:
        diff = round(weight - previous_weight, 1)
        sure = f"{days_passed} gün"
        if days_passed >= 7:
            sure = f"{days_passed // 7} hafta {days_passed % 7} gün"

    if (goal or "").lower() == "kas kazanma":  # B14: goal None → AttributeError guard
        # Kas kazanmada kilo artışı OLUMLU
        if diff > 0:
            progress_text = (
                f"Kullanıcı {sure} önce {previous_weight} kg'dı, "
                f"şimdi {weight} kg — {abs(diff)} kg almış. "
                f"KAS KAZANMA hedefinde bu bir BAŞARI. Tebrik et. "
                f"Kalori fazlası doğru çalışıyor, devam etmesini söyle."
            )
        elif diff < 0:
            progress_text = (
                f"Kullanıcı {sure} önce {previous_weight} kg'dı, "
                f"şimdi {weight} kg — {abs(diff)} kg vermiş. "
                f"KAS KAZANMA hedefinde bu istenmeyen bir durum. "
                f"Kalori alımını artırması gerektiğini vurgula. "
                f"Kalori açığı değil, kalori fazlası hedefleniyor."
            )
        else:
            progress_text = (
                f"Kullanıcı {sure} önce de {previous_weight} kg'dı, kilo değişmemiş. "
                f"KAS KAZANMA hedefinde kilo artışı bekleniyor. "
                f"Kalori alımını biraz artırmasını öner."
            )
    else:
        # Kilo verme hedefinde
        if diff < 0:
            progress_text = (
                f"Kullanıcı {sure} önce {previous_weight} kg'dı, "
                f"şimdi {weight} kg — {abs(diff)} kg vermiş. "
                f"KİLO VERME hedefinde bu bir BAŞARI. Tebrik et. "
                f"Verme hızını değerlendir: {sure}de {abs(diff)} kg."
            )
        elif diff > 0:
            progress_text = (
                f"Kullanıcı {sure} önce {previous_weight} kg'dı, "
                f"şimdi {weight} kg — {abs(diff)} kg almış. "
                f"KİLO VERME hedefinde bu istenmeyen bir durum. "
                f"Nazikçe değin, kalori takibine odaklanmasını söyle."
            )
        else:
            progress_text = (
                f"Kullanıcı {sure} önce de {previous_weight} kg'dı, kilo değişmemiş. "
                f"KİLO VERME hedefinde plato olabilir. "
                f"Kalori açığını gözden geçirmesini öner."
            )
    if _coach_lang(language) == "en":
        lang_line = ('You speak ENGLISH. Address the user directly as "you". Write your '
                     'ENTIRE answer in English and translate the Turkish section headers '
                     'below into natural English headers.')
    else:
        lang_line = ('Türkçe konuşuyorsun. Kullanıcıya "sen" diye hitap et, hiçbir zaman '
                     '"siz" kullanma. Yanıtında tek bir İngilizce kelime bile kullanma, '
                     'tamamen Türkçe yaz.')

    prompt = f"""Sen deneyimli, samimi ve motive edici bir kişisel fitness koçusun.
Şeker boyamıyorsun ama insanı kırmıyorsun da.
{lang_line}
Tavsiyelerin bu kişinin spesifik verilerine dayansın — genel geçer şeyler söyleme.
"ÇOK ÖNEMLİ: Kas kazanma hedefinde kilo artışı OLUMLUDUR, bunu asla negatif algılama. "
"Kilo verme hedefinde kilo azalışı OLUMLUDUR. "
"Hedefe göre değerlendirme yap, genel kalıplarla düşünme."

Kullanıcı bilgileri:
- İsim: {name}, Yaş: {age}, Cinsiyet: {gender}
- Güncel kilo: {weight}kg, Boy: {height}cm
- BMR: {round(bmr)} kcal, TDEE: {round(tdee)} kcal
- Hedef kalori: {round(target_calories)} kcal/gün
- Hedef: {goal}
- Fitness seviyesi: {level}
- Günlük aktivite: {activity_text}
- Kullanıcının sorusu/mesajı: {user_message if user_message else 'Yok'}

İlerleme durumu:
{progress_text}

Aşağıdaki formatta kişiye özel koçluk yorumu yaz:

GENEL DEĞERLENDİRME:
(2-3 cümle — mevcut durumu ve ilerlemeyi değerlendir, sayıları kullan)

EN KRİTİK ADIM:
(şu an odaklanması gereken tek şey, spesifik ve ölçülebilir olsun)

BU HAFTA YAP:
1. (spesifik görev — gün, süre, miktar belirt)
2. (spesifik görev — gün, süre, miktar belirt)
3. (spesifik görev — gün, süre, miktar belirt)

MOTİVASYON:
(bu kişinin durumuna özel, güçlü bir cümle)"""

    try:
        return _heavy_chat(
            messages=[{"role": "user", "content": prompt}],
            system_prompt=("You are a fitness coach. Speak English — friendly, specific, "
                           "motivating; use numbers and durations."
                           if _coach_lang(language) == "en"
                           else "Sen bir fitness koçusun. Türkçe, samimi, spesifik ve motive edici konuş. Sayılar ve süreler kullan."),
            max_tokens=700,
            temperature=0.7,
        )
    except Exception:
        current_app.logger.exception("Koç yorumu üretilemedi")
        return ("Coach feedback is unavailable right now, please try again."
                if _coach_lang(language) == "en"
                else "Koç yorumu şu an alınamıyor, lütfen tekrar dene.")


def generate_checkin_feedback(name, weight, prev_weight, days_passed,
                               goal, yogunluk, fatigue, overload,
                               uyku, beslenme, note, language="tr"):

    yogunluk_labels = {1:"çok düşük",2:"düşük",3:"orta",4:"yüksek",5:"çok yüksek"}
    fatigue_labels  = {1:"hiç yorgun değil",2:"biraz yorgun",3:"normal",4:"yorgun",5:"çok yorgun"}
    overload_labels = {"evet":"ağırlık/tekrar artırdı","hayir":"artıramadı","kismen":"kısmen artırdı"}
    uyku_labels     = {1:"çok kötü",2:"kötü",3:"orta",4:"iyi",5:"çok iyi"}
    beslenme_labels = {1:"hiç uyamadı",2:"zayıf",3:"orta",4:"iyi",5:"tam uyum"}

    progress = "İlk check-in, geçmiş veri yok."
    if prev_weight and days_passed:
        diff = round(weight - prev_weight, 1)
        if (goal or "").lower() == "kas kazanma":  # B14: goal None guard
            if diff > 0:
                progress = f"{days_passed} günde {abs(diff)} kg aldı — kas kazanma hedefinde olumlu."
            elif diff < 0:
                progress = f"{days_passed} günde {abs(diff)} kg verdi — kas kazanma hedefinde bu istenmeyen."
            else:
                progress = f"{days_passed} günde kilo değişmedi — kalori artışı gerekebilir."
        else:
            if diff < 0:
                progress = f"{days_passed} günde {abs(diff)} kg verdi — kilo verme hedefinde başarılı."
            elif diff > 0:
                progress = f"{days_passed} günde {abs(diff)} kg aldı — kilo verme hedefinde istenmeyen."
            else:
                progress = f"{days_passed} günde kilo değişmedi — plato olabilir."

    checkin_lang = ('Write your ENTIRE feedback in English; address the user as "you". '
                    'The data below is in Turkish — translate it as needed.'
                    if _coach_lang(language) == "en"
                    else 'Türkçe yaz, İngilizce kullanma. Kullanıcıya "sen" diye hitap et.')

    prompt = f"""Sen bir kişisel fitness koçusun. {checkin_lang}

Haftalık check-in verileri:
- İsim: {name}
- Güncel kilo: {weight} kg
- Hedef: {goal}
- İlerleme: {progress}
- Antrenman yoğunluğu: {yogunluk_labels.get(yogunluk, 'orta')}
- Yorgunluk durumu: {fatigue_labels.get(fatigue, 'normal')}
- Progressive overload: {overload_labels.get(overload, 'kısmen')}
- Uyku kalitesi: {uyku_labels.get(uyku, 'orta')}
- Beslenme uyumu: {beslenme_labels.get(beslenme, 'orta')}
- Kullanıcının notu: {note if note else 'Yok'}

Bu verilere dayanarak kısa ve spesifik bir koçluk geri bildirimi yaz.
Maksimum 4-5 cümle. İyi giden şeyleri vurgula, eksik olanlar için somut öneri ver.
Fatigue yüksekse dinlenme öner, progressive overload yapamadıysa nasıl yapabileceğini anlat.
Uyku kötüyse bunun etkisini açıkla."""

    try:
        return _heavy_chat(
            messages=[{"role": "user", "content": prompt}],
            system_prompt=("You are a fitness coach. Speak concise, specific, motivating English."
                           if _coach_lang(language) == "en"
                           else "Sen bir fitness koçusun. Kısa, spesifik, motive edici Türkçe konuş."),
            max_tokens=400,
            temperature=0.7,
        )
    except Exception:
        current_app.logger.exception("Check-in geri bildirimi üretilemedi")
        return ("Feedback is unavailable right now, please try again."
                if _coach_lang(language) == "en"
                else "Geri bildirim şu an alınamadı, lütfen tekrar dene.")
